import { selectVisible } from "./repository.mjs";
import { MAX_PAGE_SIZE } from "./limits.mjs";
export function listPage(records, {after=null,limit=2}={}) { const start=after===null?0:records.findIndex(row=>row.id===after); const batch=records.slice(start,start+limit); return {items:selectVisible(batch),nextCursor:batch.at(-1)?.id??null}; }
